```js
const fs = require('node:fs');
const { exec } = require('node:child_process');

async function run(name, dest) {
  if (fs.existsSync(dest)) {
    console.error('exists');
    process.exit(1);
  }
  exec(`convert ${name} out.png`, (err, stdout) => {
    if (err.message.includes('not found')) console.log('missing tool');
    fs.createReadStream('out.png').pipe(fs.createWriteStream(dest));
  });
}

process.on('uncaughtException', (e) => console.error(e));
